argv:
$ErrorActionPreference='Stop'
$dir='E:\WebAIBridge-R69-OBSERVABILITY-20261014-GPT6'
$sha='03e8ec94e59ef4efbb748afed418eafada844add'
if(Test-Path -LiteralPath $dir){throw 'R69_DESTINATION_ALREADY_EXISTS'}
& git.exe clone --quiet --depth 1 --single-branch --no-tags --branch 'agent/r69-durable-viewer-lifecycle-20261014' 'https://github.com/foto6/WebAIBridge.git' $dir
if($LASTEXITCODE -ne 0){throw 'R69_CLONE_FAILED'}
$head=([string](& git.exe -C $dir rev-parse HEAD)).Trim()
if($head -ne $sha){throw ('R69_SHA_MISMATCH '+$head)}
$log=Join-Path $dir 'R69_STARTUP_TESTS.txt'
$syntax=Join-Path $dir 'R69_UI_CHECK.js'
Push-Location -LiteralPath (Join-Path $dir 'app')
try {
 & node.exe --test r69-viewer-bootstrap.test.js r68-live-chat-observability.test.js r68-live-viewer.test.js autonomous-send-gate-r50.test.js r65-global-canary-cap.test.js *> $log
 $rc=$LASTEXITCODE
 & node.exe --check server.js
 $srcRc=$LASTEXITCODE
 $view=Get-Content -LiteralPath 'ui.html' -Raw
 $match=[regex]::Match($view,'(?s)<script>(.*?)</script>')
 if(-not $match.Success){throw 'DASHBOARD_SCRIPT_MISSING'}
 [IO.File]::WriteAllText($syntax,$match.Groups[1].Value,[Text.UTF8Encoding]::new($false))
 & node.exe --check $syntax
 $uiRc=$LASTEXITCODE
}finally{Pop-Location}
Write-Output ('R69_SHA='+$head)
Write-Output ('TEST_EXIT='+$rc)
Write-Output ('SERVER_SYNTAX_EXIT='+$srcRc)
Write-Output ('INTEGRATED_UI_SYNTAX_EXIT='+$uiRc)
Select-String -LiteralPath $log -Pattern '^ℹ (?:tests|pass|fail|skipped)|^✖'|Select-Object -Last 12|ForEach-Object{Write-Output $_.Line}
Write-Output ('PRODUCTION_HEAD='+(& git.exe -C 'E:\WebAIBridge' rev-parse HEAD))
if($rc -ne 0 -or $srcRc -ne 0 -or $uiRc -ne 0){throw 'R69_TESTS_FAILED'}
